/* ---- build the deck ---------------------------------------------------- */
const track = document.getElementById('track');

function mediaHTML(s, i){
  const m = MEDIA[s.key];
  if(!m.video) return '<img src="' + m.poster + '" alt="">';
  /* only the first two are fetched up front. The rest pull when you approach
     them, with the poster covering the wait. */
  return '<video class="film" src="' + m.video + '" poster="' + m.poster + '" ' +
         'autoplay muted loop playsinline preload="' + (i < 2 ? 'auto' : 'metadata') + '"></video>';
}

function sheetHTML(s, i){
  const copy = s.layout === 'card'
    ? '<div class="card paper ' + (s.pos || 'br') + '">' +
        '<div class="cardhead">' +
          (s.eyebrow ? '<p class="ceyebrow">' + s.eyebrow + '</p>' : '') +
          '<h2>' + s.title.join('<br>') + '</h2>' +
        '</div>' +
        (s.lede ? '<p class="cbody">' + s.lede + '</p>' : '') +
        (s.cta ? '<a class="btn" href="#"><span><em>' + s.cta + '</em></span></a>' : '') +
      '</div>'
    : '<div class="stack">' +
        (s.eyebrow ? '<p class="eyebrow">' + s.eyebrow + '</p>' : '') +
        '<div class="lead"><h1>' + s.title.join('<br>') + '</h1>' +
        (s.lede ? '<p class="lede">' + s.lede + '</p>' : '') + '</div>' +
      '</div>' +
      (s.link ? '<a class="footlink" href="#">' + s.link + '</a>' : '');

  return '<div class="scene">' + mediaHTML(s, i) + '</div>' + copy + '<div class="under"></div>';
}

SCENES.forEach((s, i) => {
  const el = document.createElement('section');
  el.className = 'panel';
  el.innerHTML =
    '<div class="sheet">' + sheetHTML(s, i) + '</div>' +
    '<div class="gutter"></div><div class="spine"></div><div class="shade"></div><div class="glare"></div>';
  track.appendChild(el);
});

/* ---- the bend ----------------------------------------------------------
   A sheet of paper does not swing like a door, it bows. The turning section
   is rebuilt as a chain of vertical slices, each hinged on the one before
   it, and the turn is shared unevenly across those hinges: almost nothing at
   the bound edge, most of it out at the free edge. */
const K = 12;

function buildBend(hostEl, sheetEl, cls){
  const bend = document.createElement('div');
  bend.className = cls || 'bend';
  bend.setAttribute('aria-hidden', 'true');
  const slices = [];
  let parent = bend;
  for(let j = 0; j < K; j++){
    const sl = document.createElement('div');
    sl.className = 'sl';

    const clip = document.createElement('div');
    clip.className = 'clip';
    const copy = sheetEl.cloneNode(true);
    copy.classList.add('copy');
    copy.style.left = 'calc(var(--u) * ' + (-j) + ')';
    copy.querySelectorAll('a,button,input,select,textarea')
        .forEach(n => n.setAttribute('tabindex', '-1'));
    /* a clone must never carry an id: the visible cover is twelve of these,
       so an id inside it would exist thirteen times and getElementById would
       hand back a hidden one */
    if(copy.id) copy.removeAttribute('id');
    copy.querySelectorAll('[id]').forEach(n => n.removeAttribute('id'));
    /* twelve live videos in the chain would be twelve decoders. A page being
       turned is frozen anyway, so the copies carry the poster still. */
    copy.querySelectorAll('video').forEach(v => {
      const still = document.createElement('img');
      still.src = v.getAttribute('poster');
      still.alt = '';
      v.replaceWith(still);
    });
    const sh = document.createElement('i'); sh.className = 'sh';
    const gl = document.createElement('i'); gl.className = 'gl';
    clip.appendChild(copy); clip.appendChild(sh); clip.appendChild(gl);

    const bk = document.createElement('div');
    bk.className = 'bk';

    sl.appendChild(clip); sl.appendChild(bk);
    parent.appendChild(sl);
    parent = sl;
    slices.push({ sl, clip, bk, sh, gl, copy });
  }
  hostEl.appendChild(bend);
  return slices;
}

function bendChain(slices, d, sweep){
  const k = d * d * d * (d * (d * 6 - 15) + 10);
  const total = (sweep != null ? sweep : TUNE.sweep) * k;
  /* Split the turn into a rigid part and a bowed part. The rigid part all
     happens at the bound edge, which is what makes the sheet lie flat and
     clear the frame at the end. Spread it evenly along the chain instead and
     the sheet curls into a circle and never leaves. */
  const bow = Math.pow(Math.sin(Math.PI * clamp(d, 0, 1)), 1.5) * TUNE.curl;
  const rigid = total * (1 - bow);
  const bowed = total * bow;

  let run = 0;
  for(let j = 0; j < K; j++){
    ANG[j] = (j === 0 ? rigid : 0) + bowed * SHAPE[j] / SHAPE_SUM;
    run += ANG[j];
    ACC[j] = run;
  }

  const peak = Math.sin(Math.PI * clamp(d, 0, 1));
  for(let j = 0; j < K; j++){
    const S = slices[j];
    S.sl.style.transform = (j ? 'translateX(100%) ' : '') + 'rotateY(' + ANG[j].toFixed(3) + 'deg)';

    /* Swap front for back by angle rather than trusting backface culling.
       Culling is unreliable on an element that overflow has flattened, and
       when it fails you see the face of the page mirrored through its own
       reverse. */
    const past = Math.abs(ACC[j]) > 90;
    S.clip.style.visibility = past ? 'hidden' : 'visible';
    S.bk.style.visibility = past ? 'visible' : 'hidden';

    /* Light is read at the joints and painted across each slice as a ramp.
       Shade a flat slice and you see the slice; shade the joints and you see
       a curve. */
    const l = j > 0 ? (ACC[j - 1] + ACC[j]) * 0.5 : ACC[0] * 0.5;
    const r = j < K - 1 ? (ACC[j] + ACC[j + 1]) * 0.5 : ACC[K - 1];
    if(past){
      S.bk.style.filter = 'brightness(' + (0.72 + 0.28 * Math.abs(Math.cos(ACC[j] * Math.PI / 180))).toFixed(3) + ')';
    } else {
      S.sh.style.background =
        'linear-gradient(90deg,rgba(28,20,10,' + shadeAt(l) + '),rgba(28,20,10,' + shadeAt(r) + '))';
      S.gl.style.background =
        'linear-gradient(90deg,rgba(255,253,246,' + specAt(l, peak) + '),rgba(255,253,246,' + specAt(r, peak) + '))';
    }
  }
}

const ANG = new Array(K).fill(0);
const ACC = new Array(K).fill(0);
const shadeAt = deg => clamp((1 - Math.abs(Math.cos(deg * Math.PI / 180))) * 0.56, 0, 0.62).toFixed(3);
const specAt = (deg, peak) =>
  (Math.pow(Math.max(0, Math.cos(deg * Math.PI / 180 + 0.62)), 14) * 0.40 * peak).toFixed(3);

/* the three numbers that decide how the turn feels. deck.tune({...}) live. */
const TUNE = { sweep: -178, curl: 0.52, bow: 1.35 };

let SHAPE = [], SHAPE_SUM = 0;
function reshape(){
  SHAPE = []; SHAPE_SUM = 0;
  for(let j = 0; j < K; j++){
    const v = Math.pow(j / (K - 1), TUNE.bow);
    SHAPE.push(v); SHAPE_SUM += v;
  }
}
reshape();

const panels = [...document.querySelectorAll('.panel')].map(el => {
  const sheet = el.querySelector('.sheet');
  return {
    el, sheet, slices: null,
    shade: el.querySelector('.shade'),
    glare: el.querySelector('.glare'),
    gutter: el.querySelector('.gutter'),
    under: el.querySelector('.sheet > .under'),
    copyEl: el.querySelector('.sheet > .card, .sheet > .stack'),
    film: el.querySelector('.sheet > .scene > video'),
    turning: false
  };
});
const N = panels.length;
document.getElementById('tot').textContent = String(N).padStart(2, '0');

/* ---- motes ---------------------------------------------------------------
   Pollen crossing the frame while the book is shut. Cheap: forty odd soft
   dots on one canvas, drawn from the frame loop that is already running.
   They stop being drawn the moment the cover has gone. */
const motesCv = document.getElementById('motes');
const mx = motesCv.getContext('2d');
let motes = [], mw = 0, mh = 0;

function seedMotes(){
  const dpr = Math.min(2, window.devicePixelRatio || 1);
  mw = innerWidth; mh = innerHeight;
  motesCv.width = Math.round(mw * dpr);
  motesCv.height = Math.round(mh * dpr);
  motesCv.style.width = mw + 'px';
  motesCv.style.height = mh + 'px';
  mx.setTransform(dpr, 0, 0, dpr, 0, 0);
  motes = Array.from({ length: 44 }, (_, i) => ({
    x: (i * 97.3) % mw,
    y: (i * 61.7) % mh,
    r: 0.7 + ((i * 7) % 10) / 5.2,          /* 0.7 to 2.6 */
    a: 0.07 + ((i * 13) % 9) / 26,          /* 0.07 to 0.38 */
    vx: 5 + ((i * 11) % 17),                /* px per second, all one way */
    vy: -3 - ((i * 5) % 9),
    ph: (i * 0.83) % 6.283,
    sw: 5 + ((i * 3) % 9)                   /* wobble */
  }));
}
seedMotes();
addEventListener('resize', seedMotes);

let motesDirty = false;
function drawMotes(dt, tsec){
  if(!motesOn){
    if(motesDirty){ mx.clearRect(0, 0, mw, mh); motesDirty = false; }
    return;
  }
  motesDirty = true;
  mx.clearRect(0, 0, mw, mh);
  for(const m of motes){
    m.x += m.vx * dt;
    m.y += m.vy * dt;
    if(m.x - m.r > mw) { m.x = -m.r; }
    if(m.y + m.r < 0)  { m.y = mh + m.r; }
    const wob = Math.sin(tsec * 0.6 + m.ph) * m.sw;
    const g = mx.createRadialGradient(m.x + wob, m.y, 0, m.x + wob, m.y, m.r * 3.2);
    g.addColorStop(0, 'rgba(255,236,190,' + m.a.toFixed(3) + ')');
    g.addColorStop(0.45, 'rgba(233,176,74,' + (m.a * 0.45).toFixed(3) + ')');
    g.addColorStop(1, 'rgba(233,176,74,0)');
    mx.fillStyle = g;
    mx.beginPath();
    mx.arc(m.x + wob, m.y, m.r * 3.2, 0, 6.283);
    mx.fill();
  }
}

/* ---- the orbit -----------------------------------------------------------
   While the book is shut the camera drifts with the pointer, so it reads as
   an object sitting in a room rather than a picture of one. Heavily damped,
   and scaled by how shut the book is, so it is gone by the time the cover
   opens and never fights the scroll geometry. */
let orbTX = 0, orbTY = 0, orbX = 0, orbY = 0;
addEventListener('pointermove', e => {
  orbTX = clamp((e.clientX / innerWidth - 0.5) * 2, -1, 1);
  orbTY = clamp((e.clientY / innerHeight - 0.5) * 2, -1, 1);
}, { passive: true });
addEventListener('pointerleave', () => { orbTX = 0; orbTY = 0; }, { passive: true });

function stepOrbit(dt){
  const ease = 1 - Math.pow(0.0009, dt);      /* about a third of a second */
  orbX += (orbTX - orbX) * ease;
  orbY += (orbTY - orbY) * ease;
}

/* ---- the way in -------------------------------------------------------- */
let motesOn = false;
const world = document.getElementById('world');
const stageEl = document.getElementById('stage');
const spotEl = document.getElementById('spot');
const motesEl = document.getElementById('motes');
const coverEl = document.querySelector('.cover');
const shadowEl = document.querySelector('.bookshadow');
const coverFace = document.getElementById('coverface');
/* the page block, built here so the markup stays about the design */
const boardEl = document.querySelector('.board');
const blockParts = ['leaf l1', 'leaf l2', 'leaf l3', 'blockedge', 'spine', 'pagemask'].map(cls => {
  const el = document.createElement('div');
  el.className = cls;
  boardEl.after(el);
  return el;
});
const maskEl = blockParts[blockParts.length - 1];
const blockEdge = { style: { set display(v){ blockParts.forEach(el => el.style.display = v); } } };

const coverSlices = buildBend(coverEl, coverFace, 'bend cover-bend');
coverFace.style.display = 'none';
document.querySelectorAll('.cover-bend').forEach(b => { b.style.visibility = 'visible'; });

const siteChrome = document.querySelector('.bottomleft');
/* the chevrons carry two reasons to be faded at once, the book being shut and
   there being nowhere to go, so they are driven in the render loop instead */
let chromeK = 1;

function drawIntro(q){
  const shut = clamp(q, 0, 1);
  const inShot = smooth(clamp((shut - 0.62) / 0.38, 0, 1));   /* 1 = far away */
  const open = smooth(clamp((0.72 - shut) / 0.52, 0, 1));     /* 1 = cover gone */

  /* the vanishing point sits at 34% for the page turn, which throws the shut
     book off centre. Walk it back to the middle while the book is flat. */
  stageEl.style.perspectiveOrigin = (34 + 16 * inShot).toFixed(2) + '% 50%';

  world.style.transform =
    'translateY(' + (inShot * 5.2).toFixed(2) + 'vh) ' +
    'translateZ(' + (-inShot * 1180).toFixed(1) + 'px) ' +
    'rotateX(' + (inShot * 46).toFixed(2) + 'deg) ' +
    'rotateZ(' + (inShot * -1.6).toFixed(2) + 'deg) ' +
    'rotateY(' + (inShot * orbX * 5.5).toFixed(2) + 'deg) ' +
    'rotateX(' + (inShot * -orbY * 3.2).toFixed(2) + 'deg)';

  /* the light pool follows the book so the spot never slides off it */
  spotEl.style.transform =
    'translate(' + (inShot * orbX * -1.1).toFixed(2) + 'vw,' +
                   (inShot * orbY * -0.7).toFixed(2) + 'vh)';

  /* display, not visibility: the slices carry an explicit visible of their
     own, and a child's explicit visible beats a hidden ancestor */
  const dead = shut <= 0.001;
  const show = dead ? 'none' : '';
  coverEl.style.display = show;
  blockEdge.style.display = show;
  boardEl.style.display = show;
  shadowEl.style.opacity = (inShot * 0.9).toFixed(3);
  shadowEl.style.display = show;
  if(!dead) bendChain(coverSlices, open, -182);

  /* the light and the motes belong to the cover, so they leave with it */
  const room = smooth(clamp((shut - 0.10) / 0.5, 0, 1));
  spotEl.style.opacity = room.toFixed(3);
  motesEl.style.opacity = (room * 0.95).toFixed(3);
  motesOn = room > 0.01;

  /* the mask goes as soon as the cover has lifted off the page */
  maskEl.style.opacity = (1 - smooth(clamp(open / 0.16, 0, 1))).toFixed(3);

  const off = smooth(clamp((shut - 0.14) / 0.44, 0, 1));
  chromeK = 1 - off;
  if (siteChrome) {
    siteChrome.style.opacity = chromeK.toFixed(3);
    siteChrome.style.pointerEvents = off > 0.5 ? 'none' : 'auto';
  }
}

/* ---- state ------------------------------------------------------------- */
const REDUCED = matchMedia('(prefers-reduced-motion: reduce)').matches;
let mode = 'turn';
let prog = -1;
let target = -1;
let idle = 0;
let dragging = false;
let held = false;

const clamp = (v, a, b) => v < a ? a : v > b ? b : v;
/* The hinge chain is twelve copies of a full frame scene, so seven of them
   standing by permanently is seven times a cost only one section is ever
   using: exactly one section is mid turn at any moment. Build the chain when
   a page starts to turn, throw it away when it stops. */
function setTurning(P, on){
  if(P.turning === on) return;
  P.turning = on;
  if(on && !P.slices) P.slices = buildBend(P.el, P.sheet);
  P.el.classList.toggle('turning', on);
  if(!on && P.slices){
    P.el.querySelector('.bend').remove();
    P.slices = null;
  }
}
const easeIn = t => t * t;
const easeOut = t => 1 - Math.pow(1 - t, 2.2);
const smooth = t => t * t * (3 - 2 * t);

function goTo(i){ target = clamp(i, -1, N - 1); idle = 0; }
function nudge(d){ goTo(Math.round(target) + d); }

/* ---- input ------------------------------------------------------------- */
addEventListener('wheel', e => {
  e.preventDefault();
  const d = Math.abs(e.deltaX) > Math.abs(e.deltaY) ? e.deltaX : e.deltaY;
  const unit = e.deltaMode === 1 ? 18 : e.deltaMode === 2 ? innerHeight : 1;
  target = clamp(target + (d * unit) / 900, -1, N - 1);
  idle = 0;
}, { passive: false });

let dragX = 0, dragFrom = 0, moved = 0;
addEventListener('pointerdown', e => {
  if(e.target.closest('button, a')) return;
  dragging = true; moved = 0;
  dragX = e.clientX; dragFrom = target;
  document.body.classList.add('dragging');
});
addEventListener('pointermove', e => {
  if(!dragging) return;
  const dx = e.clientX - dragX;
  moved = Math.max(moved, Math.abs(dx));
  target = clamp(dragFrom - dx / (innerWidth * 0.78), -1, N - 1);
  idle = 0;
});
addEventListener('pointerup', () => {
  if(!dragging) return;
  dragging = false;
  document.body.classList.remove('dragging');
  if(moved < 6) return;
  const v = target - dragFrom;
  if(Math.abs(v) > 0.12 && Math.abs(v) < 0.6) target = clamp(dragFrom + Math.sign(v), -1, N - 1);
  idle = 999;
});

addEventListener('keydown', e => {
  const k = e.key;
  if(k === 'ArrowRight' || k === 'ArrowDown' || k === 'PageDown' || k === ' '){ e.preventDefault(); nudge(1); }
  else if(k === 'ArrowLeft' || k === 'ArrowUp' || k === 'PageUp'){ e.preventDefault(); nudge(-1); }
  else if(k === 'Home'){ goTo(-1); }
  else if(k === 'End'){ goTo(N - 1); }
});

const prevBtn = document.getElementById('prev');
const nextBtn = document.getElementById('next');
prevBtn.addEventListener('click', () => nudge(-1));
nextBtn.addEventListener('click', () => nudge(1));


/* Film only runs on the section you are actually looking at. Everything else
   is paused and rewound to frame zero, which is the poster the hinge chain
   shows, so a page settling back into place cannot jump mid clip.

   play() returns a promise that a browser can reject for reasons that have
   nothing to do with this code, so a rejection is remembered rather than
   retried sixty times a second, and the first real user gesture clears every
   flag and asks again. Muted autoplay is normally allowed, but this way the
   scroll that opens the book is itself the permission. */
let filmBlocked = false;
function runFilm(){
  panels.forEach((P, i) => {
    if(!P.film) return;
    const near = Math.abs(prog - i) < 0.8 && !P.turning;
    if(near){
      if(P.film.paused && !P.filmPending && !P.filmDenied){
        P.filmPending = true;
        P.film.play().then(() => { P.filmPending = false; })
                     .catch(() => { P.filmPending = false; P.filmDenied = true; filmBlocked = true; });
      }
    } else if(!P.film.paused){
      P.film.pause();
      P.film.currentTime = 0;
    }
  });
}
function kickFilm(){
  if(!filmBlocked) return;
  filmBlocked = false;
  panels.forEach(P => { P.filmDenied = false; });
}
['pointerdown','wheel','keydown','touchstart'].forEach(ev =>
  window.addEventListener(ev, kickFilm, { passive: true }));

/* ---- sound -------------------------------------------------------------
   Two beds on a Web Audio graph. The medieval loop runs from the moment
   sound is enabled to the moment it is turned off. The mystery ambience only
   exists inside the cave: it is started when the mix opens and stopped when
   it closes, so it is not quietly burning a decoder for six sections.

   Web Audio rather than <audio loop> for two reasons. An AudioBufferSource
   loops sample accurately, where an <audio> element leaves an encoder gap at
   the wrap. And a GainNode ramps, where setting .volume sixty times a second
   steps and zippers.

   The clips are inlined rather than read from media/, because decodeAudioData
   needs the bytes and fetch cannot read a sibling file over file://. */
const SOUND = {"medieval": "", "mystery": ""};

const audio = {
  ctx:null, master:null, beds:{}, ready:false, on:false, failed:false,
  /* headroom, so the bed sits under the artwork rather than on top of it */
  vol:0.65,
  /* where the cave mix sits, 0 outside it and 1 in the cave */
  cave:0
};

function b64bytes(b64){
  const bin = atob(b64), buf = new Uint8Array(bin.length);
  for(let i = 0; i < bin.length; i++) buf[i] = bin.charCodeAt(i);
  return buf.buffer;
}

async function audioInit(){
  if(audio.ready || audio.failed) return audio.ready;
  try{
    const AC = window.AudioContext || window.webkitAudioContext;
    if(!AC) throw new Error('no Web Audio');
    audio.ctx = new AC();
    audio.master = audio.ctx.createGain();
    audio.master.gain.value = 0;
    audio.master.connect(audio.ctx.destination);

    const names = Object.keys(SOUND);
    const bufs = await Promise.all(names.map(n =>
      audio.ctx.decodeAudioData(b64bytes(SOUND[n]))));
    names.forEach((n, i) => {
      const g = audio.ctx.createGain();
      g.gain.value = 0;
      g.connect(audio.master);
      /* level is the AudioParam, not the node. Passing the node to a ramp
         throws, and reading .value off it silently gives undefined. */
      audio.beds[n] = { buf: bufs[i], out: g, level: g.gain, src: null };
    });
    audio.ready = true;
  }catch(e){
    audio.failed = true;
    console.warn('sound unavailable:', e && e.message);
  }
  return audio.ready;
}

function bedStart(name){
  const b = audio.beds[name];
  if(!b || b.src) return;
  const n = audio.ctx.createBufferSource();
  n.buffer = b.buf;
  n.loop = true;
  n.connect(b.out);
  n.start(0);
  b.src = n;
}
function bedStop(name){
  const b = audio.beds[name];
  if(!b || !b.src) return;
  try{ b.src.stop(); }catch(e){}
  b.src.disconnect();
  b.src = null;
  /* an exponential ramp never quite lands on zero, so pin it. Otherwise the
     next start comes in from whatever residue was left, which is an audible
     blip on re-entering the cave. */
  b.level.cancelScheduledValues(audio.ctx.currentTime);
  b.level.value = 0;
}

/* setTargetAtTime rather than assigning .value, and only when the target has
   actually moved, so a slow ramp is a handful of scheduled calls */
function ramp(param, to, tau){
  if(Math.abs(param.value - to) < 0.004) return;
  param.setTargetAtTime(to, audio.ctx.currentTime, tau);
}

async function soundOn(){
  if(!await audioInit()) return;
  if(audio.ctx.state === 'suspended') await audio.ctx.resume();
  audio.on = true;
  bedStart('medieval');
  ramp(audio.master.gain, audio.vol, 0.35);
  reflectSound();
}
function soundOff(){
  if(!audio.ready) { reflectSound(); return; }
  audio.on = false;
  ramp(audio.master.gain, 0, 0.22);
  /* let the ramp finish before the context is parked */
  setTimeout(() => {
    if(audio.on) return;
    bedStop('medieval'); bedStop('mystery');
    if(audio.ctx.state === 'running') audio.ctx.suspend();
  }, 700);
  reflectSound();
}
function soundToggle(){ audio.on ? soundOff() : soundOn(); }

const spkBtn = document.getElementById('spk');
const coverSound = document.getElementById('coverSound');
function reflectSound(){
  spkBtn.setAttribute('aria-pressed', audio.on ? 'true' : 'false');
  const label = audio.on ? 'Sound on' : 'Sound off';
  spkBtn.setAttribute('aria-label', label);
  spkBtn.setAttribute('title', label);
  coverSound.classList.toggle('gone', audio.on || audio.failed);
}
spkBtn.addEventListener('click', soundToggle);
/* decode both beds during the intro, so Enable sound is instant rather than a
   second and a half of nothing. A context may be created before a gesture; it
   simply starts suspended. */
audioInit().then(reflectSound);
document.getElementById('soundCta').addEventListener('click', soundOn);
/* the cover sits inside the 3D stage, so a press there must not also start a
   drag of the deck underneath it */
coverSound.addEventListener('pointerdown', e => e.stopPropagation());

/* the cave mix. Called from the frame loop with the deck position. */
function mixSound(){
  if(!audio.ready || !audio.on) return;
  /* The cave is the last section, index N-1. The bed starts ducking a third
     of the way into the turn that arrives there, and the mix is fully over by
     the time the page settles.

     It is a straight swap, not a duck: the medieval bed goes out and the
     mystery bed comes in. Equal power rather than linear, so the level holds
     through the middle instead of dipping where the two cross. Both beds are
     normalised to the same loudness, so 1.0 on each really is a swap. */
  const k = clamp((prog - (N - 1.7)) / 0.7, 0, 1);
  audio.cave = k;
  ramp(audio.beds.medieval.level, Math.cos(k * Math.PI / 2), 0.25);
  if(k > 0.001){
    bedStart('mystery');
    ramp(audio.beds.mystery.level, Math.sin(k * Math.PI / 2), 0.25);
  } else if(audio.beds.mystery.src){
    ramp(audio.beds.mystery.level, 0, 0.2);
    setTimeout(() => { if(audio.cave < 0.001) bedStop('mystery'); }, 600);
  }
}

/* a tab in the background should be silent */
document.addEventListener('visibilitychange', () => {
  if(!audio.ready || !audio.on) return;
  if(document.hidden) audio.ctx.suspend();
  else audio.ctx.resume();
});

/* ---- render ------------------------------------------------------------ */
const rail = document.getElementById('rail');
for(let i = 0; i < N; i++){
  const seg = document.createElement('span');
  seg.innerHTML = '<i></i>';
  rail.appendChild(seg);
}
const marks = [...rail.querySelectorAll('i')];
const idxEl = document.getElementById('idx');
const hintEl = document.getElementById('hint');
let last = performance.now();

function frame(now){
  const dt = Math.min(0.05, (now - last) / 1000);
  last = now;
  idle += dt;

  /* settle onto a whole section once input stops, so every rest state is a
     composed frame rather than a half turn */
  if(!dragging && !held && idle > 0.16){
    const snap = Math.round(target);
    target += (snap - target) * (1 - Math.pow(0.00006, dt));
  }
  if(!held) prog += (target - prog) * (REDUCED ? 1 : 1 - Math.pow(0.0016, dt));

  stepOrbit(dt);
  drawIntro(-prog);
  drawMotes(dt, now / 1000);
  const deckProg = Math.max(0, prog);

  for(let i = 0; i < N; i++){
    const P = panels[i];
    const d = deckProg - i;

    if(d <= -1.001 || d >= 0.998){
      if(P.el.style.visibility !== 'hidden'){
        P.el.style.visibility = 'hidden';
        setTurning(P, false);
      }
      continue;
    }
    P.el.style.visibility = 'visible';

    let t = '', shade = 0, glare = 0, gutter = 0, under = 0, z = N - i;

    if(mode === 'turn'){
      /* A section at rest must NOT be handed to the chain. The chain hides
         the real sheet, is pointer-events none, and carries a frozen poster
         instead of the live film, so a page resting there looks nearly right
         and is dead, still and a hair narrow.

         Coming back to a section the page approaches d = 0 from above, so it
         stayed in the chain for the whole tail of the ease. The threshold is
         the sweep at that point, not the number: smootherstep(0.02) is 8e-5,
         which is fourteen thousandths of a degree. Nothing to see. */
      if(d > 0.02){
        setTurning(P, true);
        bendChain(P.slices, d);
        /* the lift ramps in FROM the threshold, not from zero. Perspective
           origin is at 34%, so any Z on a full frame page projects it
           sideways: starting the lift at zero left a step to jump at the
           handover, which is the pages arriving a hair narrow and then
           snapping. */
        t = 'translateZ(' + Math.max(0, (d - 0.02) * 22.4).toFixed(2) + 'px)';
        z = N + 20 - i;
      } else {
        setTurning(P, false);
        const k = clamp(1 + d, 0, 1);          /* 0 far, 1 seated */
        if(k >= 1){
          /* seated. No transform at all rather than an identity one, so
             there is nothing for the compositor to round differently. */
          t = 'none';
        } else {
          const s = 0.965 + 0.035 * easeOut(k);
          t = 'translateZ(' + (-70 + 70 * easeOut(k)).toFixed(2) + 'px) scale(' + s.toFixed(4) + ')';
          gutter = (1 - k) * 0.9;
          under = (1 - k) * 0.42;
        }
      }
    } else {
      setTurning(P, false);
      const x = -d * 100;
      if(d >= 0){
        const k = easeIn(d);
        t = 'translate3d(' + x.toFixed(3) + 'vw,0,' + (k * 18).toFixed(2) + 'px) rotateY(' + (-k * 34).toFixed(2) + 'deg)';
        shade = k * 0.55;
        glare = Math.sin(k * Math.PI) * 0.18;
      } else {
        const k = 1 + d;
        t = 'translate3d(' + x.toFixed(3) + 'vw,0,' + (-40 + 40 * easeOut(k)).toFixed(2) +
            'px) rotateY(' + ((1 - easeOut(k)) * 14).toFixed(2) + 'deg)';
        gutter = (1 - k) * 0.55;
        under = (1 - k) * 0.30;
      }
    }

    P.el.style.transform = t;
    P.el.style.zIndex = z;
    P.shade.style.opacity = shade.toFixed(3);
    P.glare.style.opacity = glare.toFixed(3);
    P.gutter.style.opacity = gutter.toFixed(3);
    P.under.style.opacity = under.toFixed(3);

    /* The copy travels a touch slower than its page, so the turn has depth.
       This used to be applied to the whole sheet, which meant the picture
       itself was offset by up to 4vw mid turn and slid the last pixel or so
       into place as the deck settled. That is the pages arriving short of the
       browser width and then snapping. The picture must always fill the
       frame exactly; only the copy is allowed to lag.

       It is a custom property, not a transform, for two reasons. The hero
       stack centres itself with a translate of its own and an inline
       transform would wipe that out. And custom properties inherit, so
       setting it on the panel reaches the real sheet and all twelve hinge
       clones at once. Freezing it during a turn was only ever a patch: the
       clones now read the same live value the sheet does, so the copy stays
       put across the handover instead of stepping.

       The curve matters as much as the amount. Linear in d means the copy is
       still travelling at full speed as the page seats, which is the last
       thing you see and reads as a snap. Smoothstep has zero slope at both
       ends, so the copy is already at rest by the time the page is. */
    const dd = clamp(Math.abs(d), 0, 1);
    const par = (d > 0 ? -1 : 1) * smooth(dd) * (mode === 'turn' ? 3 : 8);
    P.el.style.setProperty('--par', par.toFixed(2) + 'vw');
  }

  const cur = Math.max(0, Math.round(prog));
  idxEl.textContent = String(cur + 1).padStart(2, '0');
  for(let i = 0; i < N; i++){
    marks[i].style.transform = 'scaleX(' + clamp(prog - i + 1, 0, 1).toFixed(3) + ')';
  }
  prevBtn.disabled = prog < 0.5;
  nextBtn.disabled = prog > N - 1.5;
  prevBtn.style.opacity = (chromeK * (prevBtn.disabled ? 0.16 : 1)).toFixed(3);
  nextBtn.style.opacity = (chromeK * (nextBtn.disabled ? 0.16 : 1)).toFixed(3);
  prevBtn.style.pointerEvents = (chromeK > 0.5 && !prevBtn.disabled) ? 'auto' : 'none';
  nextBtn.style.pointerEvents = (chromeK > 0.5 && !nextBtn.disabled) ? 'auto' : 'none';
  const shut = prog < -0.08;
  hintEl.style.opacity = shut ? '1' : '0';
  coverSound.classList.toggle('away', !shut);
  runFilm();
  mixSound();

  /* blend the dark flag across the turn so the header changes with the page
     rather than after it */
  const df = clamp(deckProg, 0, N - 1);
  const da = Math.floor(df), db = Math.min(N - 1, da + 1), dmix = df - da;
  const darkK = (SCENES[da].dark ? 1 : 0) * (1 - dmix) + (SCENES[db].dark ? 1 : 0) * dmix;
  document.body.classList.toggle('on-dark', darkK > 0.5);

  requestAnimationFrame(frame);
}
requestAnimationFrame(frame);

/* console helpers, for reviewing */
window.deck = {
  goTo, get at(){ return prog; }, set mode(m){ mode = m; },
  hold(v){ held = true; prog = target = v; },
  release(){ held = false; },
  version: 'v12 (21 Aug 2026 10:41 UTC)',
  volume(v){
    audio.vol = clamp(v, 0, 1);
    if(audio.on) ramp(audio.master.gain, audio.vol, 0.2);
    return audio.vol;
  },
  sound(){ return { on: audio.on, ready: audio.ready, failed: audio.failed,
                    cave: +audio.cave.toFixed(3),
                    master: audio.master ? +audio.master.gain.value.toFixed(3) : null,
                    medieval: audio.beds.medieval ? +audio.beds.medieval.level.value.toFixed(3) : null,
                    mystery: audio.beds.mystery ? +audio.beds.mystery.level.value.toFixed(3) : null,
                    mysteryRunning: !!(audio.beds.mystery && audio.beds.mystery.src) }; },
  tune(o){ Object.assign(TUNE, o); reshape(); return TUNE; },
  mode(m){
    mode = m;
    document.getElementById('stage').style.perspectiveOrigin = m === 'turn' ? '34% 50%' : '50% 50%';
    return mode;
  },
  /* if a clip ever refuses to play, this says why in one line per section */
  films(){
    return panels.map((P, i) => P.film ? {
      scene: i + 1, src: P.film.currentSrc.split('/').pop(),
      readyState: P.film.readyState, networkState: P.film.networkState,
      duration: +P.film.duration.toFixed(2), t: +P.film.currentTime.toFixed(2),
      paused: P.film.paused, denied: !!P.filmDenied, error: P.film.error && P.film.error.message
    } : { scene: i + 1, film: null });
  }
};
